import{_ as p,a0 as o,w as l,s as r,ao as d,I as n,x as e,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何使用 rsync 通过 SSH 恢复部分传输的文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 rsync 通过 SSH 恢复部分传输的文件 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 rsync 通过 SSH 恢复部分传输的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 rsync 通过 SSH 恢复部分传输的文件 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180129 How To Resume Partially Transferred Files Over SSH Using Rsync","title":"如何使用 rsync 通过 SSH 恢复部分传输的文件","tag":"201805","desc":""},"relativePath":"201805/20180129 How To Resume Partially Transferred Files Over SSH Using Rsync.md","filePath":"[post].md"}'),c={name:"201805/20180129 How To Resume Partially Transferred Files Over SSH Using Rsync.md"};function h(u,s,g,k,b,y){const i=o("Link");return l(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何使用-rsync-通过-ssh-恢复部分传输的文件" tabindex="-1">如何使用 rsync 通过 SSH 恢复部分传输的文件 <a class="header-anchor" href="#如何使用-rsync-通过-ssh-恢复部分传输的文件" aria-label="Permalink to “如何使用 rsync 通过 SSH 恢复部分传输的文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/02/Resume-Partially-Transferred-Files-Over-SSH-Using-Rsync.png" alt=""></p><p>由于诸如电源故障、网络故障或用户干预等各种原因，使用 <code>scp</code> 命令通过 SSH 复制的大型文件可能会中断、取消或损坏。有一天，我将 Ubuntu 16.04 ISO 文件复制到我的远程系统。不幸的是断电了，网络连接立即断了。结果么？复制过程终止！这只是一个简单的例子。Ubuntu ISO 并不是那么大，一旦电源恢复，我就可以重新启动复制过程。但在生产环境中，当你在传输大型文件时，你可能并不希望这样做。</p><p>而且，你不能继续使用 <code>scp</code> 命令恢复被中止的进度。因为，如果你这样做，它只会覆盖现有的文件。这时你会怎么做？别担心！这是 <code>rsync</code> 派上用场的地方！<code>rsync</code> 可以帮助你恢复中断的复制或下载过程。对于那些好奇的人，<code>rsync</code> 是一个快速、多功能的文件复制程序，可用于复制和传输远程和本地系统中的文件或文件夹。</p><p>它提供了大量控制其各种行为的选项，并允许非常灵活地指定要复制的一组文件。它以增量传输算法而闻名，它通过仅发送源文件和目标中现有文件之间的差异来减少通过网络发送的数据量。 <code>rsync</code> 广泛用于备份和镜像，以及日常使用中改进的复制命令。</p><p>就像 <code>scp</code> 一样，<code>rsync</code> 也会通过 SSH 复制文件。如果你想通过 SSH 下载或传输大文件和文件夹，我建议您使用 <code>rsync</code>。请注意，应该在两边（远程和本地系统）都安装 <code>rsync</code> 来恢复部分传输的文件。</p><h3 id="使用-rsync-恢复部分传输的文件" tabindex="-1">使用 rsync 恢复部分传输的文件 <a class="header-anchor" href="#使用-rsync-恢复部分传输的文件" aria-label="Permalink to “使用 rsync 恢复部分传输的文件”">​</a></h3><p>好吧，让我给你看一个例子。我将使用命令将 Ubuntu 16.04 ISO 从本地系统复制到远程系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>这里，</p><ul><li><code>sk</code>是我的远程系统的用户名</li><li><code>192.168.43.2</code> 是远程机器的 IP 地址。</li></ul><p>现在，我按下 <code>CTRL+C</code> 结束它。</p><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk@192.168.43.2&#39;s password: </span></span>
<span class="line"><span>ubuntu-16.04-desktop-amd64.iso 26% 372MB 26.2MB/s 00:39 ETA^c</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/02/scp.png" alt=""></p><p>正如你在上面的输出中看到的，当它达到 26％ 时，我终止了复制过程。</p><p>如果我重新运行上面的命令，它只会覆盖现有的文件。换句话说，复制过程不会在我断开的地方恢复。</p><p>为了恢复复制过程，我们可以使用 <code>rsync</code> 命令，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -P -rsh=ssh Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sk@192.168.1.103&#39;s password:</span></span>
<span class="line"><span>sending incremental file list</span></span>
<span class="line"><span>ubuntu-16.04-desktop-amd64.iso</span></span>
<span class="line"><span>                   380.56M 26% 41.05MB/s 0:00:25</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/02/rsync.png" alt=""></p><p>看见了吗？现在，复制过程在我们之前断开的地方恢复了。你也可以像下面那样使用 <code>-partial</code> 而不是 <code>-P</code> 参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync --partial -rsh=ssh Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>这里，参数 <code>-partial</code> 或 <code>-P</code> 告诉 <code>rsync</code> 命令保留部分下载的文件并恢复进度。</p><p>或者，我们也可以使用以下命令通过 SSH 恢复部分传输的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rsync -avP Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rsync -av --partial Soft_Backup/OS\\ Images/Linux/ubuntu-16.04-desktop-amd64.iso sk@192.168.43.2:/home/sk/</span></span></code></pre></div><p>就是这样了。你现在知道如何使用 <code>rsync</code> 命令恢复取消、中断和部分下载的文件。正如你所看到的，它也不是那么难。如果两个系统都安装了 <code>rsync</code>，我们可以轻松地通过上面描述的那样恢复复制的进度。</p><p>如果你觉得本教程有帮助，请在你的社交、专业网络上分享，并支持我们。还有更多的好东西。敬请关注！</p><p>干杯!</p><hr>`,33)),n("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.ostechnix.com/how-to-resume-partially-downloaded-or-transferred-files-using-rsync/"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/how-to-resume-partially-downloaded-or-transferred-files-using-rsync/",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[6]||(s[6]=e(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...s[3]||(s[3]=[e("geekpi",-1)])]),_:1}),s[7]||(s[7]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[e("Linux中国",-1)])]),_:1}),s[12]||(s[12]=e(" 荣誉推出",-1))])])}const w=p(c,[["render",h]]);export{S as __pageData,w as default};
